sys_ui_action.client_script_v2:
function onClick(g_form) {
    getMessages(['Work notes', 'Cancel Case', 'Provide a reason for cancelling the case.', 'Enter a reason for canceling', 'This action can\'t be undone.', 'Don\'t cancel', 'Cancel case'], function() {
        var fields = [{
            type: 'textarea',
            name: 'work_notes',
            label: getMessage('Work notes')
        }];

        var sysId = g_form.getUniqueValue();
        var tblName = g_form.getTableName();

        g_modal.showFields({
            title: getMessage('Enter a reason for canceling'),
            fields: fields,
            instruction: getMessage('This action can\'t be undone.'),
            size: 'md',
            cancelTitle: getMessage('Don\'t cancel'),
            confirmTitle: getMessage('Cancel case'),
            cancelStyle: 'default',
            confirmStyle: 'destructive'
        }).then(function(fieldValues) {
            //get the work note entered
            var newWorkNote = fieldValues.updatedFields[0].value;
            //Call the Ajax function that handles adding worknotes and state
            var s = new GlideAjax("sn_hr_core.hr_CaseAjax");
            s.addParam("sysparm_name", "cancelAction");
            s.addParam("sysparm_obj_id", sysId);
            s.addParam("sysparm_table_name", tblName);
            s.addParam("sysparm_work_note", newWorkNote);
            s.getXML(addWorkNotes);

            function addWorkNotes(response) {
                g_form.save();
            }
        });
    });
}

sys_ui_action.script:
/**
 * copied from https://hoccdcdv.service-now.com/sys_ui_action.do?sys_id=325370019f22120047a2d126c42e701d
 * on 2024-05-13
 * Changed condition
 */
function cancelCase() {
    var sysId = typeof rowSysId == 'undefined' || rowSysId == null ?
        g_form.getUniqueValue() : rowSysId;
    var dialogClass = GlideModal ? GlideModal : GlideDialogWindow;
    var dialog = new dialogClass('sn_hr_core_HR Comment Dialog');
    var msg = new GwtMessage().getMessage('Enter the reason for canceling the case');
    dialog.setTitle(msg);
    dialog.setPreference('sysparm_task_sys_id', sysId);
    dialog.setPreference('sysparm_task_table', 'sn_hr_core_case');
    dialog.setPreference('sysparm_ok_method_name', 'cancelCase');
    /* [HOC CUSTOMIZATION - value on following line] */
    dialog.setPreference('sysparm_is_required', 'true');
    dialog.setPreference('sysparm_is_comment', 'false');
    dialog.on('hrComentDialogSucess', function() {
        dialog.destroy();
        gsftSubmit(null, g_form.getFormElement(), 'sysverb_update_and_stay');
    });
    dialog.render();
    return;
}
